CREATE OR REPLACE FUNCTION private.validate_wing_media_photo_vote()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_photo public.wing_media_submissions%rowtype;
  -- Match JavaScript String.trim in the gallery, including non-ASCII whitespace.
  v_consent_whitespace constant text := U&'\0009\000a\000b\000c\000d\0020\00a0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200a\2028\2029\202f\205f\3000\feff';
begin
  if tg_op = 'UPDATE' and (new.submission_id is distinct from old.submission_id
                           or new.user_id is distinct from old.user_id) then
    raise exception 'photo vote identity cannot change' using errcode = '42501';
  end if;

  if new.user_id is distinct from (select auth.uid())
     or coalesce((auth.jwt()->>'is_anonymous')::boolean, false) then
    raise exception 'photo vote requires a signed-in user' using errcode = '42501';
  end if;

  select * into v_photo
  from public.wing_media_submissions
  where id = new.submission_id;

  if not found or v_photo.media_type is distinct from 'photo'
     or v_photo.status is distinct from 'approved'
     or v_photo.user_id is null or v_photo.owner_deleted_at is not null
     or v_photo.withdrawn_at is not null
     or nullif(pg_catalog.btrim(v_photo.consent_version, v_consent_whitespace), '') is null
     or v_photo.consented_at is null or v_photo.consented_at > now()
     or v_photo.attribution_preference not in ('username', 'display_name', 'anonymous')
     or v_photo.processed_storage_path is distinct from
        'processed/' || v_photo.id::text || '/primary'
     or not exists (
       select 1 from storage.objects object
       where object.bucket_id = 'wing-submissions'
         and object.name = v_photo.processed_storage_path
     ) then
    raise exception 'photo is not eligible for voting' using errcode = '42501';
  end if;

  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.refresh_wing_media_photo_vote_counts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_submission_id uuid;
  -- Keep the post-lock eligibility check identical to the validation above.
  v_consent_whitespace constant text := U&'\0009\000a\000b\000c\000d\0020\00a0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200a\2028\2029\202f\205f\3000\feff';
begin
  v_submission_id := coalesce(new.submission_id, old.submission_id);
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('wing-photo-votes:' || v_submission_id::text, 0)
  );

  update public.wing_media_submissions s
  set like_count = (
        select count(*)::integer from public.wing_media_photo_votes v
        where v.submission_id = v_submission_id and v.vote = 1
      ),
      dislike_count = (
        select count(*)::integer from public.wing_media_photo_votes v
        where v.submission_id = v_submission_id and v.vote = -1
      )
  where s.id = v_submission_id
    and (tg_op = 'DELETE' or (
      s.media_type = 'photo' and s.status = 'approved'
      and s.user_id is not null and s.owner_deleted_at is null
      and s.withdrawn_at is null
      and nullif(pg_catalog.btrim(s.consent_version, v_consent_whitespace), '') is not null
      and s.consented_at <= now()
      and s.attribution_preference in ('username', 'display_name', 'anonymous')
      and s.processed_storage_path = 'processed/' || s.id::text || '/primary'
      and exists (
        select 1 from storage.objects object
        where object.bucket_id = 'wing-submissions'
          and object.name = s.processed_storage_path
      )
    ));
  if not found and tg_op <> 'DELETE' then
    raise exception 'photo is not eligible for voting' using errcode = '42501';
  end if;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION private.require_authenticated_user()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_anonymous boolean := coalesce((auth.jwt()->>'is_anonymous')::boolean, false);
begin
  if v_user_id is null or v_anonymous then
    raise exception 'authentication_required' using errcode = '42501';
  end if;
  return v_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.validate_wing_jury_vote_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare
  v_user_id uuid := private.require_authenticated_user();
begin
  if new.user_id is distinct from v_user_id then
    raise exception 'wing_jury_vote_owner_mismatch' using errcode = '42501';
  end if;
  -- Hold eligibility metadata steady until the vote and its counts commit.
  perform 1 from public.wing_media_submissions photo
   where photo.id = new.submission_id for share;
  perform 1 from storage.objects object
   where object.bucket_id = 'wing-submissions'
     and object.name = 'processed/' || new.submission_id::text || '/primary'
   for share;
  if not private.is_public_wing_jury_photo(new.submission_id) then
    raise exception 'photo_is_not_eligible_for_wing_jury' using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.enforce_wing_jury_vote_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
begin
  -- Account or media parent disappearance permits only its FK-driven cascade.
  -- Withdrawal retains immutable votes; direct verdict edits remain forbidden.
  if tg_op = 'DELETE' and not exists (
    select 1 from auth.users account where account.id = old.user_id
  ) then
    return old;
  end if;
  if tg_op = 'DELETE' and not exists (
    select 1 from public.wing_media_submissions photo where photo.id = old.submission_id
  ) then return old; end if;
  raise exception 'wing_jury_vote_is_immutable' using errcode = '42501';
end;
$function$

CREATE OR REPLACE FUNCTION public.wing_jury_randomized_feed_candidates(p_latitude double precision, p_longitude double precision, p_user_id uuid, p_judged_submission_ids uuid[], p_session_id uuid, p_snapshot_at timestamp with time zone, p_after_page integer, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_session private.wing_jury_feed_sessions%rowtype;
  v_selected uuid[] := '{}'::uuid[];
  v_choice record;
  v_tier integer;
  v_count integer;
  v_now timestamptz;
  v_page integer := coalesce(p_after_page,0)+1;
BEGIN
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 24 THEN RAISE EXCEPTION 'invalid_feed_limit'; END IF;
  IF p_session_id IS NULL OR p_snapshot_at IS NULL OR NOT isfinite(p_snapshot_at)
    OR p_snapshot_at > clock_timestamp()
    OR p_after_page IS NULL OR p_after_page < 0 THEN RAISE EXCEPTION 'invalid_feed_session'; END IF;
  IF (p_latitude IS NULL) <> (p_longitude IS NULL) OR
    (p_latitude IS NOT NULL AND NOT(p_latitude BETWEEN -90 AND 90 AND p_longitude BETWEEN -180 AND 180)) THEN RAISE EXCEPTION 'invalid_feed_location'; END IF;
  IF cardinality(p_judged_submission_ids)>500 OR array_position(p_judged_submission_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'invalid_feed_exclusions'; END IF;
  -- Serialize allocation and retry for a session without exposing private tables.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_session_id::text,0));
  -- Explicit expiry checks below enforce TTL independently of housekeeping.
  -- Bounded TTL cleanup; unfinished sessions cannot grow indefinitely over time.
  DELETE FROM private.wing_jury_feed_sessions expired WHERE expired.id IN (
    SELECT session.id FROM private.wing_jury_feed_sessions session WHERE session.expires_at<clock_timestamp() ORDER BY session.expires_at LIMIT 20 FOR UPDATE SKIP LOCKED
  );
  SELECT * INTO v_session FROM private.wing_jury_feed_sessions session WHERE session.id=p_session_id FOR UPDATE;
  IF NOT FOUND THEN
    IF p_after_page<>0 OR p_snapshot_at<=clock_timestamp()-interval '15 minutes' THEN RAISE EXCEPTION 'expired_feed_session'; END IF;
    -- Dedicated private creation log. Serialize count/insert
    -- across all new sessions; no client IP, guest ID or session ID is a rate key.
    PERFORM pg_advisory_xact_lock(hashtextextended('wing_jury_randomized_creation',0));
    v_now:=clock_timestamp();
    DELETE FROM private.wing_jury_session_creation_log WHERE id IN (
      SELECT id FROM private.wing_jury_session_creation_log WHERE created_at<v_now-interval '1 hour' ORDER BY created_at LIMIT 200 FOR UPDATE SKIP LOCKED
    );
    IF (SELECT count(*) FROM private.wing_jury_session_creation_log WHERE created_at>=v_now-interval '1 minute')>=120
      OR (SELECT count(*) FROM private.wing_jury_session_creation_log)>=1000
      OR (SELECT count(*) FROM private.wing_jury_session_creation_log WHERE principal IS NOT DISTINCT FROM p_user_id AND created_at>=v_now-interval '1 minute')>=(CASE WHEN p_user_id IS NULL THEN 30 ELSE 10 END)
      OR (SELECT count(*) FROM private.wing_jury_session_creation_log WHERE principal IS NOT DISTINCT FROM p_user_id AND created_at>=v_now-interval '1 hour')>=(CASE WHEN p_user_id IS NULL THEN 300 ELSE 60 END)
      OR (SELECT count(*) FROM private.wing_jury_feed_sessions)>=1000 THEN
      -- Return instead of raising so bounded housekeeping commits on rejection.
      RETURN jsonb_build_object('error','feed_rate_limited');
    END IF;
    INSERT INTO private.wing_jury_session_creation_log(principal,created_at)
      VALUES(p_user_id,v_now);
    INSERT INTO private.wing_jury_feed_sessions(id,principal,latitude,longitude,snapshot_at,expires_at)
      VALUES(p_session_id,p_user_id,p_latitude,p_longitude,p_snapshot_at,p_snapshot_at+interval '15 minutes') RETURNING * INTO v_session;
    INSERT INTO private.wing_jury_feed_manifest(session_id,submission_id,destination_id,tier,shuffle_key)
      WITH candidates AS (
        SELECT photo.id,photo.destination_id,
          CASE WHEN p_latitude IS NOT NULL AND destination.lat BETWEEN -90 AND 90 AND destination.lng BETWEEN -180 AND 180
          THEN 2*6371000*asin(sqrt(least(1::double precision,greatest(0::double precision,
            power(sin(radians(destination.lat::double precision-p_latitude)/2),2)
            +cos(radians(p_latitude))*cos(radians(destination.lat::double precision))*power(sin(radians(destination.lng::double precision-p_longitude)/2),2))))) ELSE NULL END AS distance
        FROM public.wing_media_submissions photo JOIN public.destinations destination ON destination.id=photo.destination_id
        WHERE photo.created_at<=p_snapshot_at AND private.is_public_wing_jury_photo(photo.id)
          AND (p_user_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.wing_jury_votes vote WHERE vote.submission_id=photo.id AND vote.user_id=p_user_id))
          AND (p_user_id IS NOT NULL OR NOT(photo.id=ANY(coalesce(p_judged_submission_ids,'{}'::uuid[]))))
      )
      SELECT p_session_id,candidate.id,candidate.destination_id,
        CASE WHEN candidate.distance IS NULL THEN 4 WHEN candidate.distance<=25*1609.344 THEN 0
          WHEN candidate.distance<=50*1609.344 THEN 1 WHEN candidate.distance<=100*1609.344 THEN 2
          WHEN candidate.distance<=250*1609.344 THEN 3 ELSE 4 END,
        md5(p_session_id::text||candidate.id::text) FROM candidates candidate LIMIT 10001;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    IF v_count>10000 OR (SELECT count(*) FROM private.wing_jury_feed_manifest)>250000 THEN
      DELETE FROM private.wing_jury_feed_sessions WHERE id=p_session_id;
      RETURN jsonb_build_object('error','feed_capacity_exceeded');
    END IF;
  ELSIF v_session.expires_at<=clock_timestamp() THEN
    RAISE EXCEPTION 'expired_feed_session';
  ELSIF v_session.snapshot_at IS DISTINCT FROM p_snapshot_at THEN
    RAISE EXCEPTION 'invalid_feed_snapshot';
  ELSIF v_session.principal IS DISTINCT FROM p_user_id OR v_session.latitude IS DISTINCT FROM p_latitude
    OR v_session.longitude IS DISTINCT FROM p_longitude
    THEN RAISE EXCEPTION 'invalid_feed_session'; END IF;
  UPDATE private.wing_jury_feed_sessions session SET expires_at=least(session.snapshot_at+interval '24 hours',clock_timestamp()+interval '24 hours') WHERE session.id=p_session_id;
  SELECT page.submission_ids INTO v_selected FROM private.wing_jury_feed_pages page WHERE page.session_id=p_session_id AND page.page_number=v_page;
  IF NOT FOUND THEN
    IF v_page>10001 OR (SELECT count(*) FROM private.wing_jury_feed_pages)>=250000 THEN RETURN jsonb_build_object('error','feed_capacity_exceeded'); END IF;
    IF p_after_page<>v_session.last_page THEN RAISE EXCEPTION 'invalid_feed_page'; END IF;
    -- Discard new withdrawals/votes without renumbering the remaining snapshot.
    UPDATE private.wing_jury_feed_manifest manifest SET consumed=true
      WHERE manifest.session_id=p_session_id AND NOT manifest.consumed AND (
        NOT private.is_public_wing_jury_photo(manifest.submission_id)
        OR (p_user_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.wing_jury_votes vote WHERE vote.submission_id=manifest.submission_id AND vote.user_id=p_user_id))
        OR (p_user_id IS NULL AND manifest.submission_id=ANY(coalesce(p_judged_submission_ids,'{}'::uuid[])))
      );
    v_selected:='{}'::uuid[];
    FOR photo_number IN 1..p_limit LOOP
      SELECT min(manifest.tier) INTO v_tier FROM private.wing_jury_feed_manifest manifest WHERE manifest.session_id=p_session_id AND NOT manifest.consumed;
      EXIT WHEN v_tier IS NULL;
      SELECT manifest.submission_id,manifest.destination_id INTO v_choice
        FROM private.wing_jury_feed_manifest manifest WHERE manifest.session_id=p_session_id AND NOT manifest.consumed AND manifest.tier=v_tier
        ORDER BY (manifest.destination_id IS NOT DISTINCT FROM v_session.last_destination_id),manifest.shuffle_key,manifest.submission_id LIMIT 1;
      UPDATE private.wing_jury_feed_manifest manifest SET consumed=true WHERE manifest.session_id=p_session_id AND manifest.submission_id=v_choice.submission_id;
      v_selected:=array_append(v_selected,v_choice.submission_id);
      v_session.last_destination_id:=v_choice.destination_id;
    END LOOP;
    INSERT INTO private.wing_jury_feed_pages VALUES(p_session_id,v_page,v_selected);
    UPDATE private.wing_jury_feed_sessions session SET last_page=v_page,last_destination_id=v_session.last_destination_id WHERE session.id=p_session_id;
  END IF;
  RETURN jsonb_build_object(
    'page_number',v_page,
    'snapshot_at',to_char(v_session.snapshot_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'has_more',EXISTS(SELECT 1 FROM private.wing_jury_feed_manifest manifest WHERE manifest.session_id=p_session_id AND NOT manifest.consumed)
      OR EXISTS(SELECT 1 FROM private.wing_jury_feed_pages page WHERE page.session_id=p_session_id AND page.page_number>v_page),
    'candidates',coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'id',photo.id,'destination_id',photo.destination_id,'user_id',photo.user_id,
        'media_type',photo.media_type,'status',photo.status,'processed_storage_path',photo.processed_storage_path,
        'owner_deleted_at',photo.owner_deleted_at,'withdrawn_at',photo.withdrawn_at,'consent_version',photo.consent_version,
        'consented_at',photo.consented_at,'attribution_preference',photo.attribution_preference,
        'created_at',to_char(photo.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'page_number',v_page
      ) ORDER BY selected.ordinal)
      FROM unnest(v_selected) WITH ORDINALITY selected(id,ordinal) JOIN public.wing_media_submissions photo ON photo.id=selected.id
      WHERE private.is_public_wing_jury_photo(photo.id)
        AND (p_user_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.wing_jury_votes vote WHERE vote.submission_id=photo.id AND vote.user_id=p_user_id))
        AND (p_user_id IS NOT NULL OR NOT(photo.id=ANY(coalesce(p_judged_submission_ids,'{}'::uuid[]))))
    ),'[]'::jsonb)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.wing_jury_randomized_session_snapshot(p_session_id uuid, p_user_id uuid, p_latitude double precision, p_longitude double precision)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v_session private.wing_jury_feed_sessions%rowtype;
BEGIN
  SELECT * INTO v_session FROM private.wing_jury_feed_sessions WHERE id=p_session_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_session.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'expired_feed_session'; END IF;
  IF v_session.principal IS DISTINCT FROM p_user_id OR v_session.latitude IS DISTINCT FROM p_latitude
    OR v_session.longitude IS DISTINCT FROM p_longitude THEN RAISE EXCEPTION 'invalid_feed_session'; END IF;
  RETURN to_char(v_session.snapshot_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
END; $function$

CREATE OR REPLACE FUNCTION public.wingman_create_destination(p_destination jsonb, p_created_by uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 n text := btrim(p_destination->>'name'); a text := btrim(p_destination->>'address');
 c text := btrim(p_destination->>'city'); st integer := (p_destination->>'state_id')::integer;
 latitude numeric := nullif(p_destination->>'lat','')::numeric;
 longitude numeric := nullif(p_destination->>'lng','')::numeric;
 d public.destinations; matches integer;
begin
 if n is null or n='' or a is null or a='' or c is null or c='' or st is null
   or latitude is null or longitude is null or latitude not between -90 and 90 or longitude not between -180 and 180
 then raise exception 'restaurant_location_required'; end if;
 -- Serialize with all destination writes, including old clients, while looking
 -- for an existing identity. Held only during this short database transaction.
 lock table public.destinations in share row exclusive mode;
 select count(*) into matches from public.destinations x
 where x.state_id=st and lower(btrim(x.name))=lower(n)
 and (lower(btrim(x.address))=lower(a) or lower(btrim(x.city))=lower(c));
 if matches>1 then raise exception 'restaurant_match_ambiguous'; end if;
 if matches=1 then
   select * into d from public.destinations x where x.state_id=st and lower(btrim(x.name))=lower(n)
   and (lower(btrim(x.address))=lower(a) or lower(btrim(x.city))=lower(c));
   -- Same name/city with a different address might be another branch. Do not
   -- silently merge it or create a likely duplicate; require operator resolution.
   if lower(btrim(coalesce(d.address,'')))<>lower(a) then raise exception 'restaurant_match_ambiguous'; end if;
 else
   insert into public.destinations(name,address,city,state_id,lat,lng,created_by)
   values(n,a,c,st,latitude,longitude,p_created_by) returning * into d;
 end if;
 return to_jsonb(d);
end;
$function$

CREATE OR REPLACE FUNCTION public.mango_review_restaurant(p_suggestion_id uuid, p_reviewer_id uuid, p_action text, p_note text, p_destination jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.destination_suggestions; r public.restaurant_suggestion_reviews; d jsonb;
begin
 if not exists (select 1 from public.app_user_roles where user_id=p_reviewer_id and active and revoked_at is null
 and role in ('wing_reviewer','wing_admin')) then raise exception 'restaurant_reviewer_required'; end if;
 if p_action is null or p_action not in ('approve','reject') or p_note is null or length(btrim(p_note)) not between 8 and 2000
 then raise exception 'restaurant_review_invalid'; end if;
 select * into s from public.destination_suggestions where id=p_suggestion_id for update;
 if not found then raise exception 'restaurant_suggestion_not_found'; end if;
 select * into r from public.restaurant_suggestion_reviews where suggestion_id=s.id;
 if found then
   if r.action=p_action and r.reviewer_id=p_reviewer_id and r.reviewer_note=btrim(p_note)
      and r.destination_details is not distinct from (case when p_action='approve' then p_destination else null end)
   then return to_jsonb(r); end if;
   raise exception 'restaurant_already_reviewed';
 end if;
 if p_action='approve' then
   if (p_destination->>'state_id')::integer is distinct from s.state_id then raise exception 'restaurant_state_mismatch'; end if;
   d := public.wingman_create_destination(p_destination,s.user_id);
 end if;
 insert into public.restaurant_suggestion_reviews(suggestion_id,action,reviewer_id,reviewer_note,destination_id,destination_details)
 values(s.id,p_action,p_reviewer_id,btrim(p_note),(d->>'id')::uuid,case when p_action='approve' then p_destination else null end)
 returning * into r;
 return to_jsonb(r);
end;
$function$

CREATE OR REPLACE FUNCTION public.wingman_consume_rate_limit(p_user_id uuid, p_ip_address text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 ip text := coalesce(nullif(btrim(p_ip_address),''),'unknown'); ts timestamptz;
 hourly integer := case when p_user_id is null then 3 else 10 end;
 daily integer := case when p_user_id is null then 10 else 30 end;
 hour_count bigint; day_count bigint;
begin
 if length(ip)>200 then raise exception 'invalid_rate_limit_actor'; end if;
 -- Preserve existing anonymous semantics: it counts all calls from the IP,
 -- including signed-in calls. Acquire IP first, then user, in a fixed order.
 perform pg_advisory_xact_lock(hashtextextended('wingman-rate-ip:'||ip,0));
 if p_user_id is not null then
   perform pg_advisory_xact_lock(hashtextextended('wingman-rate-user:'||p_user_id::text,0));
 end if;
 ts := clock_timestamp();
 select count(*) filter(where created_at >= ts-interval '1 hour'),count(*)
 into hour_count,day_count from public.api_rate_limits
 where feature='wingman' and created_at >= ts-interval '24 hours'
 and ((p_user_id is not null and user_id=p_user_id) or (p_user_id is null and ip_address=ip));
 if hour_count>=hourly or day_count>=daily then return false; end if;
 insert into public.api_rate_limits(user_id,ip_address,feature,created_at)
 values(p_user_id,ip,'wingman',ts);
 return true;
end;
$function$
